// === Tab: mySketch.js ===
const PIXEL_DENSITY = 1;
const ITERATION_COUNT = 5; 

let rdShaders = [];
let drawShader;

let canvas;
let f;
let rdGraphics = [];
let textGraphic;
let frame = 0;

let control = {
	pixelSize: 1,
	brushSize: 30,
	showText: true,
	clear: clearCanvas,
	alternativeRule: false
}

window.onload = function() {
	var gui = new dat.GUI();
	gui.domElement.id = 'gui';
	gui.add(control, 'pixelSize', 1, 10, 1).name("Pixel Size");
	gui.add(control, 'brushSize', 1, 60, 1).name("Brush Size");
	gui.add(control, 'alternativeRule').name("Use Alternative Rule");
	gui.add(control, 'showText').name("Show Text");
	gui.add(control, 'clear').name("Reset");
};


function preload() {
	for(let i=0; i<ITERATION_COUNT; i++) {
		rdShaders.push(loadShader('https://openprocessing.org/sketch/1606830/files/vert.glsl', 'frag_rd.glsl'));
	}

	drawShader = loadShader('https://openprocessing.org/sketch/1606830/files/vert.glsl', 'frag_draw.glsl');
	f = loadFont("https://changwenhan-op-assets.surge.sh/JMH Typewriter dry-Thin.otf")
}

function setup() {
	pixelDensity(PIXEL_DENSITY);
	canvas = createCanvas(1000, 1000, WEBGL);
	noStroke();

	textGraphic = createGraphics(1000, 1000, WEBGL);
	textGraphic.pixelDensity(PIXEL_DENSITY);
	textGraphic.background(0);
	textGraphic.textFont(f);
	textGraphic.textSize(150);
	textGraphic.textAlign(CENTER, CENTER);
	textGraphic.fill("#ffffff");

	textGraphic.text("water ", 0, -70);
	textGraphic.text("stains", 0, 100);

	for(let i=0; i<ITERATION_COUNT; i++) {
		rdGraphics.push(createGraphics(1000, 1000, WEBGL));
		rdGraphics[i].pixelDensity(PIXEL_DENSITY);
		rdGraphics[i].background(0);
		rdGraphics[i].shader(rdShaders[i]);
		rdShaders[i].setUniform("u_text", textGraphic);
	}

	for(let i=0; i<ITERATION_COUNT; i++) {
		const prev = (i-1+ITERATION_COUNT) % ITERATION_COUNT;
		rdShaders[i].setUniform('u_canvas', rdGraphics[prev]);
	}

	shader(drawShader);
	drawShader.setUniform('u_canvas', rdGraphics[0]);
}

function draw() {
	var y = ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))-500) / min(1, windowWidth / windowHeight) + 500;

	for(let i=0; i<ITERATION_COUNT; i++) {
		rdShaders[i].setUniform("u_resolution", [width * PIXEL_DENSITY, height * PIXEL_DENSITY]);
		rdShaders[i].setUniform("u_mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) * PIXEL_DENSITY, (height-y) * PIXEL_DENSITY]);
		rdShaders[i].setUniform("u_frame", frame);
		rdShaders[i].setUniform("u_brush_size", control.brushSize);
		rdShaders[i].setUniform("u_pixel_size", control.pixelSize);
		rdShaders[i].setUniform("u_alternative_rule", control.alternativeRule);
		rdShaders[i].setUniform("u_show_text", control.showText);
		rdShaders[i].setUniform("u_mouse_pressed", ((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)));
		rdGraphics[i].fill(0);
		rdGraphics[i].rect(width * -0.5, height * -0.5, width, height);
	}

	drawShader.setUniform("u_resolution", [width * PIXEL_DENSITY, height * PIXEL_DENSITY]);
	fill(0);
	rect(width * -0.5, height * -0.5, width, height);

	frame++;
}

function clearCanvas() {
	background(0);
	frame = 0;
}

// === Tab: frag_rd.glsl ===
#define PI 3.14159265359
#define EPSILON 0.0001
#define S(a,b) smoothstep(a-EPSILON,a,b)

#ifdef GL_ES
precision mediump float;
#endif

uniform vec2 u_resolution;
uniform vec2 u_mouse;
uniform sampler2D u_canvas;
uniform sampler2D u_text;
uniform float u_frame;
uniform float u_brush_size;
uniform float u_pixel_size;
uniform bool u_alternative_rule;
uniform bool u_show_text;
uniform bool u_mouse_pressed;

vec2 get_cell_ab(vec2 uv) {
	uv = fract(uv);
	return texture2D(u_canvas, uv).rg;
}

vec2 diffuse2(vec2 uv, vec2 r, vec2 t) {
	return 
		get_cell_ab(uv        ) * -1. +
		get_cell_ab(uv + t    ) * .206 +
		get_cell_ab(uv - t    ) * .198 +
		get_cell_ab(uv     + r) * .198 +
		get_cell_ab(uv     - r) * .198 +
		get_cell_ab(uv + t + r) * .05 +
		get_cell_ab(uv + t - r) * .05 +
		get_cell_ab(uv - t + r) * .05 +
		get_cell_ab(uv - t - r) * .05;
}

vec2 diffuse(vec2 uv, vec2 r, vec2 t) {
	return 
		get_cell_ab(uv        ) * -1. +
		get_cell_ab(uv + t    ) * .46 +
		get_cell_ab(uv - t    ) * .44 +
		get_cell_ab(uv     + r) * .03 +
		get_cell_ab(uv     - r) * .03 +
		get_cell_ab(uv + t + r) * .01 +
		get_cell_ab(uv + t - r) * .01 +
		get_cell_ab(uv - t + r) * .01 +
		get_cell_ab(uv - t - r) * .01;
}

void main() {
	float c = 0.;
	vec3 col = vec3(0.);
	vec2 uv = gl_FragCoord.xy / u_resolution.xy;	
	vec2 mouse = uv*u_mouse / gl_FragCoord.xy;

	float cell_count = 1000. / u_pixel_size;

	vec2 gv = fract(uv * cell_count);
	vec2 id = floor(uv * cell_count) + vec2(.5);
	id /= cell_count;

	vec2 mouse_id = floor(cell_count * mouse) + vec2(.5);
	mouse_id /= cell_count;

	if(int(u_frame) < 1) {
		gl_FragColor = vec4(1.,0.,0.,1.);

		vec2 text_uv = id;
		text_uv.y = 1. - text_uv.y;
		float text = texture2D(u_text, text_uv).r;
		text = S(.2, text);

		if(u_show_text) {
			gl_FragColor.g = text;
		}

		return;
	}

	vec2 canvas_uv = id;
	canvas_uv.y = 1. - canvas_uv.y;

	vec2 r = vec2(1./cell_count, 0.);
	vec2 t = vec2(0., 1./cell_count);

	float DA = 0.366;
	float DB = 0.302;
	float feed = 0.031;
	float kill = 0.056;

	if(u_alternative_rule) {
		DA = 0.725;
		DB = 0.505;
		feed = 0.031;
		kill = 0.056;
	}


	vec2 prev_ab = get_cell_ab(canvas_uv);
	vec2 diffuse_ab = diffuse(canvas_uv, r, t);
	float a = prev_ab.x;
	float b = prev_ab.y;

	float delta_a = (DA * diffuse_ab.x) - a*b*b + feed*(1.-a);
	float delta_b = (DB * diffuse_ab.y) + a*b*b - (kill+feed)*b;

	float new_a = clamp(a + delta_a, 0., 1.);
	float new_b = clamp(b + delta_b, 0., 1.);


	float mouse_cir = distance(id, mouse_id);
	float mouse_cir_r = .001 * u_brush_size ;
	float mouse_cir_line = S(mouse_cir, mouse_cir_r);

	if(u_mouse_pressed) {
		new_b = clamp(new_b+mouse_cir_line, 0., 1.);	
	}


	col = vec3(new_a, new_b, 0.);

  gl_FragColor = vec4(col, 1.); 
}

// === Tab: frag_draw.glsl ===
#ifdef GL_ES
precision mediump float;
#endif

uniform vec2 u_resolution;
uniform sampler2D u_canvas;

void main() {
	vec2 uv = gl_FragCoord.xy / u_resolution.xy;	
	uv.y = 1. - uv.y;
	vec4 texture = texture2D(u_canvas, uv);
	float amount = texture.g;

	vec3 color1 = vec3(.95, .89, .91);
	vec3 color2 = vec3(.11, .06, .27);

	amount = smoothstep(0.2, 0.4, amount);
	vec3 col = mix(color1, color2, amount);
  gl_FragColor = vec4(col, 1.0);
}

// === Tab: vert.glsl ===
 attribute vec3 aPosition;
 attribute vec2 aTexCoord;
 uniform mat4 uProjectionMatrix;
 uniform mat4 uModelViewMatrix;
 varying vec2 vTexCoord;

 void main() {
	 vTexCoord = aTexCoord;
	 vec4 position = vec4(aPosition, 1.0);
	 gl_Position = uProjectionMatrix * uModelViewMatrix * position;
 }

